package ports

import (
	"context"
	"errors"
	"time"
)

var ErrUnsupportedMultipart = errors.New("native multipart is unsupported")

// Part is a backend part of one upload, identified by its opaque ETag.
type Part struct {
	Number int
	Size   int64
	ETag   string
}

// MultipartStore is implemented by object stores with native multipart
// sessions. The upload key is generated by the server inside the workspace.
type MultipartStore interface {
	StartMultipart(ctx context.Context, key string) (string, error)
	PartURL(ctx context.Context, key, id string, number int, ttl time.Duration) (string, error)
	ListParts(ctx context.Context, key, id string) ([]Part, error)
	FinishMultipart(ctx context.Context, key, id string, parts []Part) error
	AbortMultipart(ctx context.Context, key, id string) error
}
